from ta_moler.cmd.asimgr.genericasimgr import Genericasimgr


class Collectfiles(Genericasimgr):
    """Collectfiles command class."""

    def __init__(self, ne, connection, outdir='/tmp', allfile=True, prompt=None, newline_chars=None, runner=None, pw=None, options=None):
        """
        Collect files command.

        :param ne: single IP address of one site.
        :param connection: moler connection to device, terminal when command is executed.
        :param outdir: Redirects all output files to a specific directory.
        :param allfile: Get all the supported files: pm, alarm, comm
        :param prompt: expected prompt sending by device after command execution.
        :param newline_chars: Characters to split lines.
        :param runner: Runner to run command.
        :param pw: sets of credentials for the sites.
        :param options: other options as string.
        """
        super(Collectfiles, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.ne = ne
        self.pw = pw
        self.outdir = outdir
        self.allfile = allfile
        self.options = options

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = f"./collectfiles.sh -ne {self.ne}"
        if self.pw:
            cmd = f"{cmd} -pw {self.pw}"
        if self.outdir:
            cmd = f"{cmd} -outdir {self.outdir}"
        if self.allfile:
            cmd = f"{cmd} -all"
        if self.options:
            cmd = f"{cmd} {self.options}"
        return cmd


